const input = $input.first().json.body || $input.first().json;

// 兼容 Vikunja 实际格式
const event = input.event_name || input.event || 'unknown';
const data = input.data || {};
const task = data.task || {};
const project = data.project || {};
const doer = data.doer || {};

// 提取任务信息
const taskTitle = task.title || '未知任务';
const taskID = task.id || '?';
const taskDesc = task.description ? task.description.replace(/<[^>]*>/g, '').substring(0, 200) : '';
const taskDone = task.done || false;
const priority = task.priority || 0;
const percentDone = task.percent_done || 0;

// 提取项目信息
const projectName = project.title || '未知项目';
const projectID = project.id || '?';

// 提取执行人信息
const doerName = doer.username || doer.name || '系统';

// 提取时间信息
const created = task.created ? new Date(task.created).toLocaleString('zh-CN') : '';
const updated = task.updated ? new Date(task.updated).toLocaleString('zh-CN') : '';
const dueDate = task.due_date && task.due_date !== '0001-01-01T00:00:00Z' 
  ? new Date(task.due_date).toLocaleString('zh-CN') 
  : null;
const startDate = task.start_date && task.start_date !== '0001-01-01T00:00:00Z'
  ? new Date(task.start_date).toLocaleString('zh-CN')
  : null;

// 提取看板/桶信息
const buckets = task.buckets || [];
const bucketName = buckets[0]?.title || '';
const bucketID = buckets[0]?.id || '';

// 提取标签和指派
const labels = task.labels || [];
const assignees = task.assignees || [];
const assigneeNames = assignees.map(a => a.username || a.name).join(', ') || '未分配';

// 事件映射
const eventMap = {
  'task.created': { emoji: '✅', action: '新任务创建', color: 'green' },
  'task.updated': { emoji: '📝', action: '任务更新', color: 'blue' },
  'task.deleted': { emoji: '❌', action: '任务删除', color: 'red' },
  'task.comment.created': { emoji: '💬', action: '新评论', color: 'purple' },
  'task.comment.edited': { emoji: '✏️', action: '评论编辑', color: 'orange' },
  'task.comment.deleted': { emoji: '🗑️', action: '评论删除', color: 'grey' },
  'task.assignee.created': { emoji: '👤', action: '任务分配', color: 'cyan' },
  'task.assignee.deleted': { emoji: '👤', action: '取消分配', color: 'grey' },
  'task.attachment.created': { emoji: '📎', action: '添加附件', color: 'blue' },
  'task.attachment.deleted': { emoji: '🗑️', action: '删除附件', color: 'grey' },
  'task.overdue': { emoji: '⏰', action: '任务逾期', color: 'red' },
  'task.reminder.fired': { emoji: '🔔', action: '提醒触发', color: 'yellow' },
  'project.updated': { emoji: '📁', action: '项目更新', color: 'blue' },
  'project.deleted': { emoji: '🗑️', action: '项目删除', color: 'red' },
  'project.shared.user': { emoji: '🤝', action: '分享项目给用户', color: 'green' },
  'project.shared.team': { emoji: '👥', action: '分享项目给团队', color: 'green' }
};

const eventInfo = eventMap[event] || { emoji: '📢', action: '未知操作', color: 'grey' };

// 构建详细消息
let text = `${eventInfo.emoji} **${eventInfo.action}**\n`;
text += `━━━━━━━━━━━━━━━━━━━━\n`;
text += `📋 **${taskTitle}**  ${taskDone ? '✓' : ''}\n`;
text += `🆔 ID: #${taskID}  |  📁 ${projectName}\n`;

if (taskDesc) {
  text += `\n📝 ${taskDesc}\n`;
}

// 状态信息
let statusLine = [];
if (priority > 0) statusLine.push(`🔴 优先级: ${priority}`);
if (percentDone > 0) statusLine.push(`📊 进度: ${percentDone}%`);
if (bucketName) statusLine.push(`📂 看板: ${bucketName}`);
if (statusLine.length > 0) {
  text += `\n${statusLine.join('  |  ')}\n`;
}

// 人员信息
if (assigneeNames !== '未分配') {
  text += `\n👥 负责人: ${assigneeNames}`;
}
text += `\n👤 操作人: ${doerName}`;

// 时间信息
let timeLines = [];
if (startDate) timeLines.push(`🚀 开始: ${startDate}`);
if (dueDate) timeLines.push(`⏰ 截止: ${dueDate}`);
if (created && event === 'task.created') timeLines.push(`📅 创建: ${created}`);
if (updated && event === 'task.updated') timeLines.push(`🔄 更新: ${updated}`);

if (timeLines.length > 0) {
  text += `\n\n${timeLines.join('\n')}`;
}

// 标签
if (labels.length > 0) {
  const labelNames = labels.map(l => `#${l.title || l.name}`).join(' ');
  text += `\n\n🏷️ ${labelNames}`;
}

// 链接（如果配置了前端地址）
const vikunjaBaseUrl = 'https://your-vikunja-frontend.com'; // 修改为你的地址
if (vikunjaBaseUrl && projectID && taskID) {
  text += `\n\n🔗 [查看任务](${vikunjaBaseUrl}/projects/${projectID}/tasks/${taskID})`;
}

// 上面代码相同，只改 return 部分

const cardContent = {
  config: {
    wide_screen_mode: true
  },
  header: {
    title: {
      tag: "plain_text",
      content: `${eventInfo.emoji} ${eventInfo.action}`
    },
    subtitle: {
      tag: "plain_text",
      content: `${projectName} · #${taskID}`
    },
    template: eventInfo.color || "blue"
  },
  elements: [
    {
      tag: "div",
      text: {
        tag: "lark_md",
        content: `**${taskTitle}** ${taskDone ? '~~已完成~~' : ''}`
      }
    }
  ]
};

if (taskDesc) {
  cardContent.elements.push({
    tag: "div",
    text: {
      tag: "lark_md",
      content: taskDesc.substring(0, 500)
    }
  });
}

// 添加字段信息
const fields = [];
if (assigneeNames !== '未分配') {
  fields.push({ text: { tag: "lark_md", content: `**负责人:**\n${assigneeNames}` } });
}
if (bucketName) {
  fields.push({ text: { tag: "lark_md", content: `**看板:**\n${bucketName}` } });
}
if (dueDate) {
  fields.push({ text: { tag: "lark_md", content: `**截止时间:**\n${dueDate}` } });
}
if (percentDone > 0) {
  fields.push({ text: { tag: "lark_md", content: `**进度:**\n${percentDone}%` } });
}

if (fields.length > 0) {
  cardContent.elements.push({
    tag: "div",
    fields: fields
  });
}

cardContent.elements.push({
  tag: "note",
  elements: [
    {
      tag: "plain_text",
      content: `操作人: ${doerName} · ${new Date().toLocaleString('zh-CN')}`
    }
  ]
});

return {
  json: {
    msg_type: "interactive",
    card: cardContent
  }
};
